    if test "$NUM_CORES" -eq "0"; then
      NUM_CORES=`cat /proc/cpuinfo  | grep -c ^CPU`
    fi
    if test "$NUM_CORES" -ne "0"; then
      FOUND_CORES=yes
    fi
  elif test -x /usr/sbin/sysctl; then
